data: {"metadata":{"status":"success"},"type":"TOOL_CALL_RESULT","messageId":"3af9cb91-23b9-4fc3-9e61-4baf2193d404","toolCallId":"call_7ed7c21a506c43a2ab1fcb94","content":"     1	"use client";
     2	
     3	import { useContext, type FC, type ReactNode } from "react";
     4	import { ComposerPrimitive, QueueItemPrimitive, AuiIf, XIcon, ComposerHostConfigContext, ComposerInputHostContext, ComposerAttachments, TooltipIconButton,
     5	  useConversationComposerAwaitingReply, useConversationComposerSendGuard, useAgentUILocale } from "@za38.03/agent-ui-plugins/composer-support";
     6	import { ComposerTextareaInput } from "./textarea.js";
     7	
     8	export interface ComposerQueueLabels {
     9	  queued: string;
    10	  removeQueued: string;
    11	}
    12	
    13	export const ComposerQueue: FC<ComposerQueueLabels> = ({ queued, removeQueued }) => (
    14	  <AuiIf condition={(s) => s.thread.capabilities.queue && s.composer.queue.length > 0}>
    15	    <div data-agent-ui-owned="" data-slot="aui_composer-queue" className="border-primary/20 bg-primary/5 flex flex-col gap-1 rounded-lg border p-2">
    16	      <span data-agent-ui-owned="" className="text-muted-foreground text-xs">{queued}</span>
    17	      <ComposerPrimitive.Queue>
    18	        {() => (
    19	          <div data-agent-ui-owned="" data-slot="aui_composer-queue-item" className="flex items-center gap-2 rounded-md bg-background/60 px-2 py-1 text-sm">
    20	            <div data-agent-ui-owned="" className="min-w-0 flex-1 break-words"><QueueItemPrimitive.Text /></div>
    21	            <QueueItemPrimitive.Remove asChild>
    22	              <TooltipIconButton tooltip={removeQueued} aria-label={removeQueued} type="button" className="size-6 shrink-0">
    23	                <XIcon className="size-3.5" />
    24	              </TooltipIconButton>
    25	            </QueueItemPrimitive.Remove>
    26	          </div>
    27	        )}
    28	      </ComposerPrimitive.Queue>
    29	    </div>
    30	  </AuiIf>
    31	);
    32	
    33	export interface CanonicalComposerProps {
    34	  autoFocus?: boolean | undefined;
    35	  placeholder: string;
    36	  inputAriaLabel: string;
    37	  queueLabels: ComposerQueueLabels;
    38	  triggers?: ReactNode;
    39	  beforeInput?: ReactNode;
    40	  input?: ReactNode;
    41	  leadingActions?: ReactNode;
    42	  trailingActions?: ReactNode;
    43	  submitAction?: ReactNode;
    44	}
    45	
    46	export const CanonicalComposer: FC<CanonicalComposerProps> = ({
    47	  autoFocus,
    48	  placeholder,
    49	  inputAriaLabel,
    50	  queueLabels,
    51	  triggers,
    52	  beforeInput,
    53	  input,
    54	  leadingActions,
    55	  trailingActions,
    56	  submitAction,
    57	}) => {
    58	  const inheritedHostConfig = useContext(ComposerHostConfigContext);
    59	  const resolvedAutoFocus = autoFocus ?? inheritedHostConfig.autoFocus;
    60	  const awaitingReply = useConversationComposerAwaitingReply();
    61	  const guardSend = useConversationComposerSendGuard();
    62	
    63	  return (
    64	    <ComposerPrimitive.Unstable_TriggerPopoverRoot>
    65	    <ComposerPrimitive.Root className="aui-composer-root relative flex w-full flex-col"
    66	      onSubmit={event => { if (guardSend()) event.preventDefault(); }}>
    67	      {triggers}
    68	      <ComposerPrimitive.AttachmentDropzone asChild>
